const STATES=['B','M','E','S'], NEXT=[[1,2],[1,2],[0,3],[0,3]], resources=new Map();
const clean=values=>values.map(v=>Array.isArray(v)?clean(v):Number.isFinite(v)?v:null);
const lex=(a,b)=>{const x=Array.from(a,c=>c.codePointAt(0)),y=Array.from(b,c=>c.codePointAt(0));for(let i=0;i<Math.min(x.length,y.length);i++)if(x[i]!==y[i])return x[i]-y[i];return x.length-y.length;};
async function load(path){if(!resources.has(path))resources.set(path,fetch(new URL(path,document.baseURI)).then(async r=>{if(!r.ok)throw new Error('序列模型读取失败');const value=await r.json();if(value.arrays){value.index=new Map(value.vocabulary.map((w,i)=>[w,i]));await Promise.all(Object.entries(value.arrays).map(async([key,info])=>{const r=await fetch(new URL(info.file,new URL(path,document.baseURI)));if(!r.ok)throw new Error('二元词频读取失败');const buffer=await r.arrayBuffer();if(buffer.byteLength!==info.bytes)throw new Error('二元词频长度不符');value[key]=new Uint32Array(buffer);}));value.context=Array.from({length:value.vocabulary.length},(_,i)=>{let n=0;for(let j=value.offsets[i];j<value.offsets[i+1];j++)n+=value.counts[j];return n;});}return value;}));return resources.get(path);}
const inRanges=(char,ranges)=>ranges.some(([a,b])=>a<=char.codePointAt(0)&&char.codePointAt(0)<=b);
function tokens(text,tags){const chars=Array.from(text),values=[];let at=0;for(let i=0;i<chars.length;i++)if(tags[i]==='S'||tags[i]==='E'){values.push(chars.slice(at,i+1).join(''));at=i+1;}if(at!==chars.length)throw new Error('模型返回非法BMES');return values;}
function tagsFor(words){return words.flatMap(word=>{const n=Array.from(word).length;return n===1?['S']:['B',...Array(n-2).fill('M'),'E'];});}
function legal(tags){return ['B','S'].includes(tags[0])&&['E','S'].includes(tags.at(-1))&&tags.slice(1).every((t,i)=>NEXT[STATES.indexOf(tags[i])].includes(STATES.indexOf(t)));}
function featureRows(text,rules){const chars=Array.from(text);return chars.map((char,i)=>{const code=char.codePointAt(0),type=/^[0-9]$/.test(char)?'ascii-digit':/^[A-Za-z]$/.test(char)?'ascii-letter':code>=0xff10&&code<=0xff19?'fullwidth-digit':(code>=0x4e00&&code<=0x9fff)||(code>=0x3400&&code<=0x4dbf)?'han':inRanges(char,rules.whitespace)?'space':inRanges(char,rules.punctuation)?'punctuation':'other';const prev=chars[i-1]??'<BOS>',next=chars[i+1]??'<EOS>';return ['bias',`c[-1]=${prev}`,`c[0]=${char}`,`c[+1]=${next}`,`c[-1]+c[0]=${prev}${char}`,`c[0]+c[+1]=${char}${next}`,`type=${type}`,...(i===0?['BOS']:[]),...(i===chars.length-1?['EOS']:[])];});}
function linear(model,text,rules){const rows=featureRows(text,rules),emission=rows.map(row=>STATES.map((_,j)=>row.reduce((n,f)=>n+(model.state_weights[f]?.[j]||0),0))),constrained=model.model==='perceptron';const order=constrained?[0,1,2,3]:model.labels.map(s=>STATES.indexOf(s));const scores=[STATES.map((_,j)=>(constrained&&![0,3].includes(j))?-Infinity:(model.start?.[j]||0)+emission[0][j])],pointers=[Array(4).fill(-1)];for(let t=1;t<rows.length;t++){const row=Array(4).fill(-Infinity),back=Array(4).fill(-1);for(const j of order)for(const i of order)if(!constrained||NEXT[i].includes(j)){const v=scores[t-1][i]+model.transition[i][j]+emission[t][j];if(v>row[j]){row[j]=v;back[j]=i;}}scores.push(row);pointers.push(back);}let final=-1;for(const j of order)if((!constrained||[2,3].includes(j))&&(final<0||scores.at(-1)[j]>scores.at(-1)[final]))final=j;const path=Array(rows.length);path[path.length-1]=final;for(let t=path.length-1;t>0;t--)path[t-1]=pointers[t][path[t]];const tags=path.map(j=>STATES[j]);if(!legal(tags))throw new Error('CRF 返回非法BMES序列；保持原模型行为，不修补预测');const details=rows.map((row,t)=>{const tag=tags[t],weighted=row.map(f=>[f,model.state_weights[f]?.[path[t]]||0]);if(constrained){const previous=t?tags[t-1]:'<BOS>';weighted.push([`previous_tag=${previous} → ${tag}`,t?model.transition[path[t-1]][path[t]]:model.start[path[t]]]);}return weighted.sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])||lex(a[0],b[0])).slice(0,5);});const result={text,tokens:tokens(text,tags),tags,metadata:model.metadata};if(constrained)return {...result,scores:clean(scores),backpointer:pointers,contributions:details,update_example:model.update_example};const lse=values=>{const max=Math.max(...values);return max+Math.log(values.reduce((n,v)=>n+Math.exp(v-max),0));};const alpha=[emission[0].slice()],beta=Array(rows.length);beta[rows.length-1]=Array(4).fill(0);for(let t=1;t<rows.length;t++)alpha.push(STATES.map((_,j)=>emission[t][j]+lse(order.map(i=>alpha[t-1][i]+model.transition[i][j]))));for(let t=rows.length-2;t>=0;t--)beta[t]=STATES.map((_,i)=>lse(order.map(j=>model.transition[i][j]+emission[t+1][j]+beta[t+1][j])));const z=lse(order.map(j=>alpha.at(-1)[j]));return {...result,marginals:alpha.map((row,t)=>row.map((v,j)=>Math.exp(v+beta[t][j]-z))),features:details,transitions:model.display_transition};}
function hmm2(model,text){const chars=Array.from(text),vocab=new Map(model.vocabulary.map((c,i)=>[c,i])),log=v=>v>0?Math.log(v):-Infinity;const emission=chars.map(c=>model.emission.map(row=>log(row[vocab.get(c)??0])));const score=chars.map(()=>STATES.map(()=>Array(4).fill(-Infinity))),back=chars.map(()=>STATES.map(()=>Array(4).fill(-1)));const first=model.start.map((v,i)=>[0,3].includes(i)?log(v)+emission[0][i]:-Infinity);for(let j=0;j<4;j++)score[0][j][j]=first[j];if(chars.length>1){for(let i=0;i<4;i++)for(let j=0;j<4;j++)if(NEXT[i].includes(j))score[1][i][j]=first[i]+log(model.initial[i][j])+emission[1][j];for(let t=2;t<chars.length;t++)for(let s=0;s<4;s++)for(let u=0;u<4;u++){let best=-Infinity,prev=0;for(let r=0;r<4;r++){const value=NEXT[r].includes(s)&&NEXT[s].includes(u)?score[t-1][r][s]+log(model.tensor[r][s][u]):-Infinity;if(value>best){best=value;prev=r;}}score[t][s][u]=best+emission[t][u];back[t][s][u]=prev;}}let best=-Infinity,previous=0,current=0;for(let i=0;i<4;i++)for(let j=0;j<4;j++)if([2,3].includes(j)&&score.at(-1)[i][j]>best){best=score.at(-1)[i][j];previous=i;current=j;}if(!Number.isFinite(best))throw new Error('二阶Viterbi无有效合法路径');const path=Array(chars.length);path[path.length-1]=current;if(path.length>1)path[path.length-2]=previous;for(let t=path.length-1;t>1;t--)path[t-2]=back[t][path[t-1]][path[t]];const tags=path.map(i=>STATES[i]);return {model:'hmm2',states:STATES,tokens:tokens(text,tags),tags,score:clean(score),backpointer:back,best_log_probability:best};}
function bigram(model,text,rules,tracing){const chars=Array.from(text),n=chars.length,v=model.vocabulary.length,BOS=v-3,EOS=v-2,UNK=v-1;const states=Array.from({length:n+1},()=>new Map()),lattice=[],edges=[];states[0].set('<BOS>',{cost:0,predecessor:[null,null]});function probability(previous,word){const context=model.index.get(previous)??UNK,target=word==='<EOS>'?EOS:model.index.get(word)??UNK,frequency=target===EOS?model.sentence_count:model.unigram[target],backoff=(frequency+model.alpha)/(model.token_total+model.sentence_count+model.alpha*(v-1));if(!model.context[context])return backoff;let lo=model.offsets[context],hi=model.offsets[context+1]-1,count=0;while(lo<=hi){const mid=(lo+hi)>>1;if(model.targets[mid]===target){count=model.counts[mid];break;}if(model.targets[mid]<target)lo=mid+1;else hi=mid-1;}return model.interpolation*count/model.context[context]+(1-model.interpolation)*backoff;}for(let start=0;start<n;start++){const candidates=[chars[start]];if(!inRanges(chars[start],rules.whitespace))for(let end=start+2;end<=Math.min(n,start+model.max_word_length);end++){if(inRanges(chars[end-1],rules.whitespace))break;const word=chars.slice(start,end).join('');if(model.index.has(word))candidates.push(word);}for(const word of candidates){const end=start+Array.from(word).length;if(tracing)lattice.push({start,end,word});let best=null;for(const [previous,state]of states[start]){const edgeCost=-Math.log(probability(previous,word)),cost=state.cost+edgeCost;if(tracing)edges.push({from:[start,previous],to:[end,word],negative_log_cost:edgeCost,cumulative_cost:cost});if(!best||cost<best.cost)best={cost,predecessor:[start,previous]};}if(best)states[end].set(word,best);}}let word=null,cost=Infinity;for(const [candidate,state]of states[n]){const value=state.cost-Math.log(probability(candidate,'<EOS>'));if(value<cost){cost=value;word=candidate;}}const eosCost=-Math.log(probability(word,'<EOS>')),output=[];let end=n;while(end){output.push(word);[end,word]=states[end].get(word).predecessor;}output.reverse();const chain=[];let at=0,previous='<BOS>';for(const word of output){const end=at+Array.from(word).length;chain.push({start:at,end,previous,word});at=end;previous=word;}for(const edge of edges){const state=states[edge.to[0]].get(edge.to[1]);edge.probability=Math.exp(-edge.negative_log_cost);edge.best_to_state=JSON.stringify(state.predecessor)===JSON.stringify(edge.from)&&Math.abs(state.cost-edge.cumulative_cost)<=Math.max(1e-10,1e-9*Math.abs(state.cost));edge.on_best_path=chain.some(c=>c.start===edge.from[0]&&c.end===edge.to[0]&&c.previous===edge.from[1]&&c.word===edge.to[1]);}return {model:'bigram',tokens:output,tags:tagsFor(output),cost,eos_cost:eosCost,lattice,edges,states:states.map(row=>Object.fromEntries(row)),optimal_chain:chain,solver:'词图上的 Viterbi / 最短路径动态规划'};}
export async function sequence(path,params,body,manifest){const name=path==='/api/v1/course/sequence'?body.model:path==='/api/v1/analyze'?body.segmentation_model:params.get('model'),descriptor=manifest.sequence?.models?.[name];if(!descriptor)return undefined;if(!['/api/v1/course/sequence','/api/v1/analyze','/api/v1/experiments/1/trace'].includes(path))return undefined;const text=path.endsWith('/trace')?params.get('text'):body.text,max=path.endsWith('/trace')?30:path.includes('/course/')?500:5000;if(typeof text!=='string'||!text||Array.from(text).length>max)throw new Error(`请输入1–${max}个字符`);const started=performance.now(),[model,rules]=await Promise.all([load(descriptor.path),load(manifest.sequence.unicode_path)]);let value;if(['perceptron','crf'].includes(name))return {...linear(model,text,rules),model:name==='crf'?'course-linear-chain-crf-bmes':'course-perceptron-bmes',course_extension:true,source_split:'MSR official training internal subset',elapsed_ms:performance.now()-started,execution:'browser'};if(name==='bigram')value=bigram(model,text,rules,path.endsWith('/trace'));else{const chars=Array.from(text),chunks=[],tags=[],output=[];for(let i=0;i<chars.length;){if(inRanges(chars[i],rules.whitespace)){chunks.push({offset:i,text:chars[i],tags:['S'],whitespace:true});tags.push('S');output.push(chars[i]);i++;continue;}let j=i+1;while(j<chars.length&&!inRanges(chars[j],rules.whitespace))j++;const chunk=hmm2(model,chars.slice(i,j).join(''));chunks.push({offset:i,text:chars.slice(i,j).join(''),...chunk});tags.push(...chunk.tags);output.push(...chunk.tokens);i=j;}value=chunks.length===1&&!chunks[0].whitespace?chunks[0]:{model:'hmm2',states:STATES,chunks,tokens:output,tags};}if(path.endsWith('/trace'))return {...value,trace_type:name==='bigram'?'bigram_lattice':'hmm2_pair_viterbi',text,character_count:Array.from(text).length,bmes_source:name==='bigram'?'derived from tokens':'model decoded path',pair_mask:NEXT.map(next=>STATES.map((_,i)=>next.includes(i)))};return {text,segmentation:{model:name,tokens:value.tokens,tags:value.tags},ner:body.tasks?.includes('ner')?{status:'unavailable',reason:'NER模型尚未加载'}:null,classification:null,run:model.run,elapsed_ms:performance.now()-started,execution:'browser'};}
